/**
 * Public entry point for svg4pdf-lib.
 *
 * This is a thin wrapper around svg-for-pdfkit. It accepts a @pdfme/pdf-lib
 * PDFPage and translates SVG markup into vector PDF operators.
 */
import { createAdapter } from "./adapter.js";
import { SVGtoPDF } from "svg-for-pdfkit";
/**
 * Draw an SVG string onto a pdf-lib PDFPage at the given position.
 *
 * @param page  Target pdf-lib page.
 * @param svg   SVG markup.
 * @param x     Left edge on the page (pt).
 * @param y     Bottom edge of the placed SVG on the page (pt).
 * @param options
 */
export function drawSvg(page, svg, x, y, options = {}) {
    const adapter = createAdapter(page, {
        fontCallback: options.fontCallback ?? options.font,
        warningCallback: options.warningCallback
    });
    // svg-for-pdfkit expects a PDFKit-like `doc`. We pass flipYAxis and
    // negateTextMatrix so the raw PDF operators match @pdfme/pdf-lib's
    // coordinate system and text matrix convention.
    SVGtoPDF(adapter, svg, x, y, {
        ...options,
        flipYAxis: true,
        negateTextMatrix: true,
        fontCallback: adapter.getFontCallback()
    });
}
